// This file is generated by AI.

import { describe, expect, it } from 'vitest';

import { presetWidth, resolutionOptions } from '../src/lib/video-preset';

describe('视频导出分辨率预设', () => {
  it('2560×1440 舞台下各档都是 16:9', () => {
    expect(presetWidth(480, 2560, 1440)).toBe(852);
    expect(presetWidth(720, 2560, 1440)).toBe(1280);
    expect(presetWidth(1080, 2560, 1440)).toBe(1920);
    expect(presetWidth(1440, 2560, 1440)).toBe(2560);
    expect(presetWidth(2160, 2560, 1440)).toBe(3840);
  });

  it('跟随非 16:9 的舞台画幅', () => {
    // 1920×1080 的舞台与 2560×1440 等比, 结果一致;
    // 1000×1000 的方舞台则宽度等于高度。
    expect(presetWidth(1080, 1920, 1080)).toBe(1920);
    expect(presetWidth(1080, 1000, 1000)).toBe(1080);
  });

  it('宽度取偶数', () => {
    expect(presetWidth(1079, 1000, 1000)).toBe(1078);
  });

  it('标签里写明实际尺寸', () => {
    const options = resolutionOptions(2560, 1440);
    expect(options.map((option) => option.value)).toEqual(['480', '720', '1080', '1440', '2160']);
    expect(options[0]?.label).toBe('480p（852 × 480）');
    expect(options[1]?.label).toBe('720p（1280 × 720）');
    expect(options[4]?.label).toBe('2160p（3840 × 2160）');
  });
});
